package vip.xiaonuo.srm.exchange;

import java.util.*;
import jakarta.validation.constraints.*;
import lombok.RequiredArgsConstructor;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import vip.xiaonuo.common.exception.CommonException;
import vip.xiaonuo.common.util.CommonCryptogramUtil;
import vip.xiaonuo.srm.api.SrmSupplierAccessApi.Context;
import vip.xiaonuo.srm.exchange.api.SrmExchangeApi;
import static vip.xiaonuo.srm.exchange.ExchangeStore.*;

@Service @RequiredArgsConstructor
public class ExchangeService implements SrmExchangeApi {
 private final ExchangeStore x;
 public record ConnectorInput(@NotBlank @Size(max=80)String name,@NotBlank @Pattern(regexp="ERP|MES|FINANCE|QMS")String system,@NotBlank @Pattern(regexp="SANDBOX|LIVE")String mode,@NotBlank @Size(max=512)String endpoint,@NotBlank @Size(max=2048)String secretCipher,boolean enabled){}
 public record Toggle(boolean enabled){}
 @Transactional public Map<String,Object> create(Context a,ConnectorInput p){x.admin(a);x.endpoint(p.system(),p.mode(),p.endpoint());String secret;try{secret=CommonCryptogramUtil.doSm2Decrypt(p.secretCipher());}catch(Exception e){throw new CommonException(400,"连接密钥传输无效");}require(secret.length()>=32&&secret.length()<=256,400,"连接密钥须为32～256字符");x.db.queryForList("SELECT ID FROM SYS_ORG WHERE ID=? FOR UPDATE",a.orgId());if(p.enabled())require(targets(a.orgId(),p.system(),p.mode()).isEmpty(),409,"同组织/系统/模式只允许一个启用连接");String id=id();try{x.db.update("INSERT INTO SRM_XCH_CONNECTOR(ID,ORG_ID,SYSTEM_KEY,NAME,MODE,ENDPOINT,SECRET_CIPHER,SECRET_FP,ENABLED,CREATED_BY,CREATED_AT) VALUES(?,?,?,?,?,?,?,?,?,?,NOW(3))",id,a.orgId(),p.system(),p.name(),p.mode(),p.endpoint(),x.crypto.encrypt(secret),cn.hutool.crypto.digest.DigestUtil.sha256Hex(secret),p.enabled(),a.userId());}catch(org.springframework.dao.DuplicateKeyException e){throw new CommonException(409,"连接名称已存在");}return view(x.connector(id));}
 @Transactional public Map<String,Object> toggle(Context a,String id,boolean enabled){x.admin(a);var c=x.connector(id);require(x.scope(a,s(c,"ORG_ID")),404,"连接不存在或无权访问");x.db.queryForList("SELECT ID FROM SYS_ORG WHERE ID=? FOR UPDATE",c.get("ORG_ID"));if(enabled)require(targets(s(c,"ORG_ID"),s(c,"SYSTEM_KEY"),s(c,"MODE")).stream().allMatch(r->id.equals(r.get("id"))),409,"已有其他启用连接");x.db.update("UPDATE SRM_XCH_CONNECTOR SET ENABLED=? WHERE ID=?",enabled,id);return view(x.connector(id));}
 private Map<String,Object> view(Map<String,Object> c){var out=new LinkedHashMap<String,Object>();for(String[] f:new String[][]{{"id","ID"},{"orgId","ORG_ID"},{"system","SYSTEM_KEY"},{"name","NAME"},{"mode","MODE"},{"endpoint","ENDPOINT"},{"secretFingerprint","SECRET_FP"},{"enabled","ENABLED"}})out.put(f[0],c.get(f[1]));out.put("ingressPath","/srm-integration/v1/ingress/"+c.get("ID"));return out;}
 public List<Map<String,Object>> connectors(Context a){x.admin(a);return x.db.queryForList("SELECT * FROM SRM_XCH_CONNECTOR ORDER BY CREATED_AT,ID").stream().filter(c->x.scope(a,s(c,"ORG_ID"))).map(this::view).toList();}
 public List<Map<String,Object>> targets(String org,String system,String mode){return x.db.queryForList("SELECT ID AS id,NAME AS name,MODE AS mode FROM SRM_XCH_CONNECTOR WHERE ORG_ID=? AND SYSTEM_KEY=? AND MODE=? AND ENABLED=true ORDER BY ID",org,system,mode);}
 public void requireTarget(String id,String org,String system,String mode){var c=x.connector(id);require(org.equals(c.get("ORG_ID"))&&system.equals(c.get("SYSTEM_KEY"))&&mode.equals(c.get("MODE"))&&Boolean.TRUE.equals(c.get("ENABLED")),403,"连接与业务来源不匹配或已停用");}
 @Transactional public String enqueue(String org,String system,String mode,String type,String businessId,long version,Map<String,Object> payload,String actor){var prior=x.db.queryForList("SELECT * FROM SRM_XCH_OUTBOX WHERE ORG_ID=? AND BUSINESS_TYPE=? AND BUSINESS_ID=? AND BUSINESS_VERSION=?",org,type,businessId,version);String hash=x.hash(payload);if(!prior.isEmpty()){require(hash.equals(prior.get(0).get("REQUEST_HASH")),409,"出站业务版本内容冲突");return s(prior.get(0),"ID");}var candidates=targets(org,system,mode);require(candidates.size()==1,503,"尚未配置唯一可用的"+system+"连接（"+mode+"）");String id=id(),event="srm-"+id;var envelope=new LinkedHashMap<String,Object>();envelope.put("eventId",event);envelope.put("type",type);envelope.put("businessId",businessId);envelope.put("version",version);envelope.put("data",payload);x.db.update("INSERT INTO SRM_XCH_OUTBOX(ID,ORG_ID,SYSTEM_KEY,MODE,CONNECTOR_ID,BUSINESS_TYPE,BUSINESS_ID,BUSINESS_VERSION,EVENT_KEY,PAYLOAD_CIPHER,REQUEST_HASH,STATUS,NEXT_RETRY_AT,CREATED_BY,CREATED_AT) VALUES(?,?,?,?,?,?,?,?,?,?,?,'PENDING',NOW(3),?,NOW(3))",id,org,system,mode,candidates.get(0).get("id"),type,businessId,version,event,x.crypto.encrypt(x.json(envelope)),hash,actor);return id;}
 public Map<String,Object> delivery(String org,String id){var rows=x.db.queryForList("SELECT ID AS id,ORG_ID AS orgId,CONNECTOR_ID AS connectorId,SYSTEM_KEY AS `system`,MODE AS mode,STATUS AS status,ATTEMPTS AS attempts,LAST_ERROR AS lastError,REMOTE_REF AS remoteRef,NEXT_RETRY_AT AS nextRetryAt,DELIVERED_AT AS deliveredAt FROM SRM_XCH_OUTBOX WHERE ID=? AND ORG_ID=?",id,org);require(rows.size()==1,404,"发送记录不存在");return rows.get(0);}
 public Map<String,Object> monitor(Context a,int current,int size){x.admin(a);require(current>=1&&size>=1&&size<=100,400,"分页范围错误");var allowed=connectors(a).stream().map(r->String.valueOf(r.get("id"))).toList();if(allowed.isEmpty())return Map.of("inbox",List.of(),"outbox",List.of(),"inboxTotal",0,"outboxTotal",0);String slots=String.join(",",Collections.nCopies(allowed.size(),"?"));var args=new ArrayList<Object>(allowed);long in=x.db.queryForObject("SELECT COUNT(*) FROM SRM_XCH_INBOX WHERE CONNECTOR_ID IN ("+slots+")",Long.class,args.toArray()),out=x.db.queryForObject("SELECT COUNT(*) FROM SRM_XCH_OUTBOX WHERE CONNECTOR_ID IN ("+slots+")",Long.class,args.toArray());args.add(size);args.add((current-1)*size);return Map.of("inbox",x.db.queryForList("SELECT ID AS id,CONNECTOR_ID AS connectorId,EVENT_KEY AS eventId,RESOURCE AS resource,BUSINESS_KEY AS businessKey,SOURCE_VERSION AS version,STATUS AS status,ATTEMPTS AS attempts,LAST_ERROR AS lastError,CREATED_AT AS createdAt FROM SRM_XCH_INBOX WHERE CONNECTOR_ID IN ("+slots+") ORDER BY CREATED_AT DESC,ID DESC LIMIT ? OFFSET ?",args.toArray()),"outbox",x.db.queryForList("SELECT ID AS id,CONNECTOR_ID AS connectorId,BUSINESS_TYPE AS type,BUSINESS_ID AS businessId,BUSINESS_VERSION AS version,EVENT_KEY AS eventId,STATUS AS status,ATTEMPTS AS attempts,LAST_ERROR AS lastError,REMOTE_REF AS remoteRef,CREATED_AT AS createdAt FROM SRM_XCH_OUTBOX WHERE CONNECTOR_ID IN ("+slots+") ORDER BY CREATED_AT DESC,ID DESC LIMIT ? OFFSET ?",args.toArray()),"inboxTotal",in,"outboxTotal",out);}
 @Transactional public void retry(Context a,String kind,String id){x.admin(a);require(Set.of("inbox","outbox").contains(kind),400,"记录类型错误");String table=kind.equals("inbox")?"SRM_XCH_INBOX":"SRM_XCH_OUTBOX";var rows=x.db.queryForList("SELECT * FROM "+table+" WHERE ID=? FOR UPDATE",id);require(rows.size()==1,404,"记录不存在");var row=rows.get(0);require(x.scope(a,s(x.connector(s(row,"CONNECTOR_ID")),"ORG_ID")),404,"记录不存在或无权访问");require(!Set.of("APPLIED","DUPLICATE","DELIVERED","INFLIGHT","CONFLICT").contains(s(row,"STATUS")),409,"已完成、冲突或发送中的记录不能重写；冲突须源系统修正");x.db.update("UPDATE "+table+" SET STATUS='RETRY',ATTEMPTS=0,LAST_ERROR=NULL,NEXT_RETRY_AT=NOW(3) WHERE ID=?",id);}
}
